code.cpp:
class Solution {
public:
    string sortString(string s) {
        int cnt[26] = {0};
        for (char c : s) {
            cnt[c - 'a']++;
        }
        string result;
        result.reserve(s.size());
        int n = (int)s.size();
        while ((int)result.size() < n) {
            for (int i = 0; i < 26; i++) {
                if (cnt[i] > 0) {
                    result += (char)('a' + i);
                    cnt[i]--;
                }
            }
            for (int i = 25; i >= 0; i--) {
                if (cnt[i] > 0) {
                    result += (char)('a' + i);
                    cnt[i]--;
                }
            }
        }
        return result;
    }
};
